import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './components/Login';
import CrearOferta from './components/CrearOferta';
import SolicitarOferta from './components/SolicitarOferta';
import LinksInscripcion from './components/LinksInscripcion';
import FormularioInscripcion from './components/FormularioInscripcion';
import { authService } from './services/api';
import Registro from './components/Registro';
import VerInscritos from './components/VerInscritos';
import MisInstructores from './components/MisInstructores';
import SolicitudesPendientes from './components/SolicitudesPendientes';
import MisOfertas from './components/MisOfertas';
import FuncionarioDashboard from './components/FuncionarioDashboard';

// ===== COMPONENTE PARA SELECCIONAR TIPO DE OFERTA (MODERNO) =====
const SeleccionarTipoOferta = ({ onSeleccionar }) => {
  return (
    <div className="max-w-6xl mx-auto">
      {/* Section Header */}
      <div className="mb-12">
        <h1 className="text-4xl md:text-5xl font-bold text-[#0b1c30] mb-2">Panel de Gestión</h1>
        <p className="text-lg text-[#45474c] max-w-2xl">
          Selecciona el tipo de programa para iniciar la creación de una nueva oferta 
        </p>
      </div>

      {/* Bento-Style Selection Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Card: REGULAR */}
        <div 
          onClick={() => onSeleccionar('regular')}
          className="group relative overflow-hidden rounded-xl bg-white shadow-sm hover:shadow-lg transition-all cursor-pointer border border-[#c5c6cd]/30 flex flex-col h-[400px]"
        >
          <div className="absolute inset-0 bg-gradient-to-br from-[#006c49]/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <div className="h-48 relative overflow-hidden">
            <img 
              className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700 scale-105 group-hover:scale-100"
              src="https://lh3.googleusercontent.com/aida-public/AB6AXuBfKY463fXE3_tymaD1wYMsFpn2zyLwnB0UoEofpwWjdUfxLSUDoqtBgFQPTRgRMf5KzhjB9wG9kNGsPKR1P8S0e0Riv9uJXCt4NnCYo614xJxYTyH6nOhxxhDREAS0ItyuiJDi8YfiN8rOGDO9W79AYXDZPRI2p_4yjaVpqX4gTtZG_TaJZVkyz8K7UrPxd07Y8s3f4CAl-iEjTm9JPvSEnlphw66NEkkea5550PIpPxiNYytKFFAIFgVSjxkKWsLcujQfvh8WjXY"
              alt="Regular"
            />
            <div className="absolute top-4 right-4 bg-[#006c49] text-white px-4 py-1 rounded-full text-xs font-medium shadow-lg">
              Institucional
            </div>
          </div>
          <div className="p-6 flex flex-col flex-1">
            <div className="flex items-center gap-4 mb-4">
              <div className="w-12 h-12 rounded-lg bg-[#006c49]/10 flex items-center justify-center text-[#006c49]">
                <span className="material-symbols-outlined text-3xl">apartment</span>
              </div>
              <h2 className="text-3xl font-semibold text-[#006c49]">REGULAR</h2>
            </div>
            
            <div className="mt-4 flex items-center gap-2 text-[#006c49] font-bold">
              <span className="text-sm">SELECCIONAR PROGRAMA</span>
              <span className="material-symbols-outlined transition-transform group-hover:translate-x-1">arrow_forward</span>
            </div>
          </div>
        </div>

        {/* Card: CAMPESENA */}
        <div 
          onClick={() => onSeleccionar('campesena')}
          className="group relative overflow-hidden rounded-xl bg-white shadow-sm hover:shadow-lg transition-all cursor-pointer border border-[#c5c6cd]/30 flex flex-col h-[400px]"
        >
          <div className="absolute inset-0 bg-gradient-to-br from-amber-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
          <div className="h-48 relative overflow-hidden">
            <img 
              className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700 scale-105 group-hover:scale-100"
              src="https://lh3.googleusercontent.com/aida-public/AB6AXuDXmrnwjAIlPHNgOnTYfEW4fkkCHjsUisKNIaKluTTqEwrNrHoBy3a4UYtjIL218y8JYF7r115p73WROEoKWKZdXosi6kestCC9Rq85hRs1SgM5cWTWxQ1w73mz-rk-da40zcUYz7r2P1HnsjyfV_pdA-z6L6Da_QPnNre2g1G0JhnzFlNJd-8kjz9iEUgulZMQo8u0pYfgWd7svgfpWe-1BEUUsAQmclbNfWrmxBpuNaXhuSixLxsAo_qigk4pbfi-8jg12O-83xc"
              alt="Campesena"
            />
            <div className="absolute top-4 right-4 bg-amber-600 text-white px-4 py-1 rounded-full text-xs font-medium shadow-lg">
              Rural 
            </div>
          </div>
          <div className="p-6 flex flex-col flex-1">
            <div className="flex items-center gap-4 mb-4">
              <div className="w-12 h-12 rounded-lg bg-amber-100 flex items-center justify-center text-amber-700">
                <span className="material-symbols-outlined text-3xl">agriculture</span>
              </div>
              <h2 className="text-3xl font-semibold text-amber-700">CAMPESENA</h2>
            </div>
            
            <div className="mt-4 flex items-center gap-2 text-amber-700 font-bold">
              <span className="text-sm">SELECCIONAR PROGRAMA</span>
              <span className="material-symbols-outlined transition-transform group-hover:translate-x-1">arrow_forward</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// Dashboard con dos columnas
const Dashboard = () => {
  const [vistaActiva, setVistaActiva] = useState('crear');
  const [modoCrearOferta, setModoCrearOferta] = useState(null);
  const user = authService.getCurrentUser();
  const userTipo = user?.tipo || 'instructor';
  
  const handleLogout = () => {
    authService.logout();
    window.location.href = '/login';
  };

  const handleSeleccionarModo = (modo) => {
    setModoCrearOferta(modo);
  };

  const handleVolverAlSelector = () => {
    setModoCrearOferta(null);
  };

  const menuItems = [
    { id: 'crear', icon: 'add_circle', label: 'Crear Oferta', instructorOnly: true },
    { id: 'misofertas', icon: 'inventory', label: 'Mis Ofertas', instructorOnly: true },
    { id: 'solicitar', icon: 'forward_to_inbox', label: 'Enviar Oferta', instructorOnly: true },
    { id: 'links', icon: 'share', label: 'Links de Inscripción', instructorOnly: true },
    { id: 'inscritos', icon: 'person_search', label: 'Ver Inscritos', instructorOnly: true },
    { id: 'solicitudes', icon: 'check_circle', label: 'Solicitudes de Validación', instructorOnly: false, coordinadorOnly: true },
    { id: 'instructores', icon: 'group', label: 'Mis Instructores', instructorOnly: false, coordinadorOnly: true }
  ];

  const visibleMenuItems = menuItems.filter(item => {
    if (userTipo === 'instructor') return item.instructorOnly !== false;
    if (userTipo === 'coordinador') return item.coordinadorOnly === true;
    return false;
  });

  return (
    <div className="min-h-screen bg-[#f8f9ff]">
      {/* Header */}
      <header className="fixed top-0 w-full z-50 flex justify-between items-center px-8 h-16 bg-[#006c49] text-white shadow-sm">
        <div className="flex items-center gap-4">
          {/* Logo redondo */}
          <img 
            src="/logosena.png" 
            alt="Logo SENA" 
            className="h-10 w-10 rounded-full object-cover bg-white p-0.5 shadow-sm"
          />
          <div className="h-8 w-px bg-white/20"></div>
          <span className="text-lg font-bold hidden md:block">Centro de Gestión de Datos SENA</span>
        </div>
        <div className="flex items-center gap-6">
          <div className="hidden md:flex items-center gap-3">
            <span className="text-xs bg-white/10 px-2 py-0.5 rounded capitalize">{userTipo}</span>
            <span className="text-sm font-bold">{user?.nombre} {user?.apellido}</span>
          </div>
          {/* Botón de Cerrar Sesión ROJO */}
          <button 
            onClick={handleLogout}
            className="flex items-center gap-2 bg-red-600 hover:bg-red-700 active:scale-95 transition-all px-3 py-1.5 rounded-lg shadow-sm font-medium text-sm"
          >
            <span className="material-symbols-outlined text-base">logout</span>
            <span className="text-sm hidden sm:inline">Cerrar Sesión</span>
          </button>
        </div>
      </header>

      <div className="flex pt-16">
        {/* Sidebar Moderno */}
        <aside className="fixed left-0 top-16 h-[calc(100vh-64px)] w-64 bg-white border-r border-[#c5c6cd] flex flex-col p-4 z-40">
          <div className="flex items-center gap-3 mb-6 p-1">
            <div className="w-10 h-10 bg-[#006c49] rounded-lg flex items-center justify-center text-white">
              <span className="material-symbols-outlined">school</span>
            </div>
            <div>
              <h3 className="text-xl font-semibold text-[#006c49] leading-none capitalize">{userTipo}</h3>
              <p className="text-xs text-[#45474c] opacity-70">SENA Dashboard</p>
            </div>
          </div>

          <nav className="flex-1 space-y-1">
            {visibleMenuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setVistaActiva(item.id);
                  if (item.id === 'crear') setModoCrearOferta(null);
                }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg border-l-4 transition-all ${
                  vistaActiva === item.id
                    ? 'bg-[#6cf8bb]/30 text-[#006c49] font-semibold border-[#006c49]'
                    : 'text-[#45474c] hover:bg-[#e5eeff] border-transparent'
                }`}
              >
                <span className="material-symbols-outlined text-xl">{item.icon}</span>
                <span className="text-sm">{item.label}</span>
              </button>
            ))}
          </nav>

          <div className="mt-auto">
            <div className="p-3 bg-[#eff4ff] rounded-xl border border-[#c5c6cd]/30 flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-[#006c49]/10 flex items-center justify-center text-[#006c49]">
                <span className="material-symbols-outlined text-2xl">admin_panel_settings</span>
              </div>
              <div className="flex flex-col overflow-hidden">
                <span className="text-xs text-[#45474c] uppercase tracking-wider">Coordinador</span>
                <span className="text-sm font-bold text-[#0b1c30] truncate">
                  {user?.coordinadorAsignado?.nombre || user?.nombre || 'No asignado'}
                </span>
              </div>
            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="ml-64 w-full h-[calc(100vh-64px)] overflow-y-auto bg-[#f8f9ff] p-8">
          <div className="max-w-6xl mx-auto">
            {vistaActiva === 'crear' && (
              modoCrearOferta === null ? (
                <SeleccionarTipoOferta onSeleccionar={handleSeleccionarModo} />
              ) : (
                <CrearOferta modo={modoCrearOferta} onVolverAlSelector={handleVolverAlSelector} />
              )
            )}
            {vistaActiva === 'misofertas' && <MisOfertas />}
            {vistaActiva === 'solicitar' && <SolicitarOferta />}
            {vistaActiva === 'links' && <LinksInscripcion />}
            {vistaActiva === 'inscritos' && <VerInscritos />}
            {vistaActiva === 'solicitudes' && <SolicitudesPendientes />}
            {vistaActiva === 'instructores' && <MisInstructores />}
          </div>
        </main>
      </div>
    </div>
  );
};

// Componente para rutas protegidas
const ProtectedRoute = ({ children }) => {
  if (!authService.isAuthenticated()) {
    return <Navigate to="/login" />;
  }
  return children;
};

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/inscribirse/:codigo" element={<FormularioInscripcion />} />
        <Route path="/login" element={<Login />} />
        <Route path="/registro" element={<Registro />} />
        <Route path="/dashboard" element={<ProtectedRoute><Dashboard /></ProtectedRoute>} />
        <Route path="/funcionario" element={<ProtectedRoute><FuncionarioDashboard /></ProtectedRoute>} />
        <Route path="/" element={<Navigate to="/login" />} />
        <Route path="*" element={<Navigate to="/login" />} />
      </Routes>
    </Router>
  );
}

export default App;
